<script>
(function(){
"use strict";
const canvas=document.getElementById('c'),ctx=canvas.getContext('2d');
const SCALE=80,GRAV=9.81,BRICK_W=0.50,BRICK_H=0.24,BRICK_FRIC=0.72,RESTITUTION=0.18,CAR_MASS=1250,CAR_W=4.2,CAR_H=1.45,GROUND_FRIC=0.85;
let W=0,H=0,DPR=1;
function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=W*DPR;canvas.height=H*DPR;canvas.style.width=W+'px';canvas.style.height=H+'px';ctx.setTransform(DPR,0,0,DPR,0,0);}
addEventListener('resize',resize);resize();

const $=id=>document.getElementById(id);
const settings={speed:22,cols:12,rows:8,layers:2,mass:2.5};
function bind(id,outId,key,fmt){const el=$(id);const upd=()=>{settings[key]=parseFloat(el.value);$(outId).textContent=fmt(settings[key]);buildScene(false);};el.addEventListener('input',upd);upd();}
let bricks=[],car=null,particles=[],skids=[],state='ready',elapsed=0,shake=0,impactDone=false,seed=1234567,wheelRot=0,carTilt=0,carSquash=0;
function rnd(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;}

function makeBrick(x,y,layer,row,col){
  const m=settings.mass;
  return {x,y,vx:0,vy:0,a:0,av:0,w:BRICK_W,h:BRICK_H,m,invM:1/m,I:m*(BRICK_W*BRICK_W+BRICK_H*BRICK_H)/12,layer,row,col,sleep:0,
    shade: layer===0?0: -layer*18};
}
function buildScene(running){
  seed=987654321; bricks=[];particles=[];skids=[];elapsed=0;shake=0;impactDone=false;wheelRot=0;carTilt=0;carSquash=0;
  // wall origin: place so wall is visible on typical screens. World x in metres, ground y=0, y up in physics (converted in draw/step with y-down internal)
  // Internal coords: x right (m), y down (m), ground at y=0, objects have y negative above ground. Easier: y is centre distance above ground -> use posY up.
  // We'll store yUp: centre height above ground.
  const wallX = 16.2; // left face approx
  for(let layer=0;layer<settings.layers;layer++){
    for(let r=0;r<settings.rows;r++){
      const stagger=(r%2)? BRICK_W*0.5:0;
      for(let c=0;c<settings.cols;c++){
        // staggered: offset row, trim last half brick visually by keeping full brick but shifted - wall stays coherent
        const x = wallX + c*BRICK_W + stagger*0.55 + layer*0.14 + BRICK_W/2;
        const y = BRICK_H/2 + r*BRICK_H + 0.001*r;
        bricks.push(makeBrick(x,y,layer,r,c));
      }
    }
  }
  car={x:3.1,y:0.62,vx:0,vy:0,a:0,av:0,w:CAR_W,h:1.05,m:CAR_MASS,invM:1/CAR_MASS,I:CAR_MASS*(CAR_W*CAR_W+1.05*1.05)/12,isCar:true,frontHit:0};
  state=running?'running':'ready';
  if(running) car.vx=settings.speed;
  $('status').textContent=running?('TEST RUNNING — '+settings.speed+' m/s'):'READY — wall standing';
  $('status').className='status'+(running?'':'');
}
bind('inSpeed','oSpeed','speed',v=>v.toFixed(0)+' m/s');
bind('inCols','oCols','cols',v=>v.toFixed(0)+' bricks');
bind('inRows','oRows','rows',v=>v.toFixed(0)+' bricks');
bind('inLayers','oLayers','layers',v=>v.toFixed(0)+' layers');
bind('inMass','oMass','mass',v=>v.toFixed(1)+' kg');
// bind calls buildScene repeatedly; final build:
buildScene(false);

$('testBtn').onclick=()=>{buildScene(true);};
$('resetBtn').onclick=()=>{buildScene(false);};
addEventListener('keydown',e=>{if(e.code==='Space'){e.preventDefault();buildScene(true);} if(e.key==='r'||e.key==='R')buildScene(false);});

// --- geometry helpers (yUp coords: x right, y up) ---
function corners(b){
  const c=Math.cos(b.a),s=Math.sin(b.a),hw=b.w/2,hh=b.h/2;
  return [[-hw,-hh],[hw,-hh],[hw,hh],[-hw,hh]].map(([lx,ly])=>({x:b.x+lx*c-ly*s, y:b.y+lx*s+ly*c, lx,ly}));
}
function axesOf(b){const c=Math.cos(b.a),s=Math.sin(b.a);return [{x:c,y:s},{x:-s,y:c}];}
function proj(pts,ax){let mn=1e9,mx=-1e9;for(const p of pts){const d=p.x*ax.x+p.y*ax.y;if(d<mn)mn=d;if(d>mx)mx=d;}return[mn,mx];}
function collide(a,b){
  const axes=[...axesOf(a),...axesOf(b)];const pa=corners(a),pb=corners(b);
  let best={pen:1e9,nx:0,ny:0};
  for(const ax of axes){
    const [a0,a1]=proj(pa,ax),[b0,b1]=proj(pb,ax);
    const pen=Math.min(a1,b1)-Math.max(a0,b0);
    if(pen<=0)return null;
    if(pen<best.pen){ // orient from a to b
      let nx=ax.x,ny=ax.y; const dx=b.x-a.x,dy=b.y-a.y; if(dx*nx+dy*ny<0){nx=-nx;ny=-ny;}
      best={pen,nx,ny};
    }
  }
  // contact point: deepest corner of b into a or vice versa, averaged heuristic
  let px=(a.x+b.x)/2, py=(a.y+b.y)/2;
  // find corner of b most opposite normal, corner of a most along normal
  let bestB=1e9,cb=null; for(const p of pb){const d=p.x*best.nx+p.y*best.ny; if(d<bestB){bestB=d;cb=p;}}
  let bestA=-1e9,ca=null; for(const p of pa){const d=p.x*best.nx+p.y*best.ny; if(d>bestA){bestA=d;ca=p;}}
  if(cb&&ca){px=(cb.x+ca.x)/2;py=(cb.y+ca.y)/2;}
  return {...best,px,py};
}
function applyImpulse(b,ix,iy,px,py){
  b.vx+=ix*b.invM; b.vy+=iy*b.invM;
  const rx=px-b.x, ry=py-b.y; b.av += (rx*iy - ry*ix)*(1/b.I) * (b.isCar?0.08:1);
}
function velAt(b,px,py){const rx=px-b.x,ry=py-b.y;return {x:b.vx - b.av*ry, y:b.vy + b.av*rx};}
function resolvePair(a,b,col){
  const {nx,ny,pen,px,py}=col;
  // positional correction
  const totalInv=a.invM+b.invM; if(totalInv===0)return;
  const corr=Math.max(pen-0.001,0)*0.65/totalInv;
  a.x-=nx*corr*a.invM; a.y-=ny*corr*a.invM; b.x+=nx*corr*b.invM; b.y+=ny*corr*b.invM;
  const va=velAt(a,px,py), vb=velAt(b,px,py);
  let rvx=vb.x-va.x, rvy=vb.y-va.y; const vn=rvx*nx+rvy*ny;
  if(vn<0){
    const e = vn < -1.0 ? RESTITUTION : 0;
    // effective mass at contact
    const ra={x:px-a.x,y:py-a.y}, rb={x:px-b.x,y:py-b.y};
    const raCn=ra.x*ny-ra.y*nx, rbCn=rb.x*ny-rb.y*nx;
    const kn=a.invM+b.invM + raCn*raCn/a.I + rbCn*rbCn/b.I;
    let j=-(1+e)*vn/kn;
    applyImpulse(a,-j*nx,-j*ny,px,py); applyImpulse(b,j*nx,j*ny,px,py);
    // friction
    const va2=velAt(a,px,py), vb2=velAt(b,px,py); rvx=vb2.x-va2.x; rvy=vb2.y-va2.y;
    const tx=-ny, ty=nx; const vt=rvx*tx+rvy*ty;
    const kt=a.invM+b.invM + (ra.x*ty-ra.y*tx)**2/a.I + (rb.x*ty-rb.y*tx)**2/b.I;
    let jt=-vt/kt; const maxF=BRICK_FRIC*j; jt=Math.max(-maxF,Math.min(maxF,jt));
    applyImpulse(a,-jt*tx,-jt*ty,px,py); applyImpulse(b,jt*tx,jt*ty,px,py);
    const impactSpeed=-vn;
    if(impactSpeed>2 && (a.isCar||b.isCar) && !impactDone){impactDone=true;shake=Math.min(14,4+impactSpeed*0.45);spawnDust(px,py,Math.min(36,8+impactSpeed*1.4|0));$('status').textContent='IMPACT — momentum transfer';$('status').className='status hit';}
    else if(impactSpeed>3.5) spawnDust(px,py,3);
  }
}
function groundResolve(b){
  const pts=corners(b);
  for(const p of pts){
    if(p.y < 0){ // below ground (yUp)
      const v=velAt(b,p.x,p.y);
      // positional: lift body by penetration along y approx
      b.y += (-p.y)*0.9;
      if(v.y<0){
        const rx=p.x-b.x, ry=p.y-b.y;
        const kn=b.invM + (rx*0 - ry*1)**2 / b.I * 0 + (rx)**2/b.I; // normal (0,1) up: torque term (r x n)^2/I = rx^2/I
        let j=-(1+(v.y<-1?RESTITUTION*0.6:0))*v.y/kn;
        if(j<0)j=0;
        applyImpulse(b,0,j,p.x,p.y);
        // friction along x
        const v2=velAt(b,p.x,p.y); const jt=-v2.x/(b.invM + (ry)**2/b.I); const maxF=GROUND_FRIC*j;
        const cjt=Math.max(-maxF,Math.min(maxF,jt)); applyImpulse(b,cjt,0,p.x,p.y);
      }
      // rolling / ground damping for low speeds
      if(Math.abs(b.vy)<0.05) b.vy=0;
    }
  }
  if(b.y < b.h/2 && Math.abs(b.a% (Math.PI))<0.1){ /* resting aid */ }
}
