  for(let i=0;i<n;i++){ const a=rnd()*Math.PI*2, sp=0.5+rnd()*3.2;
    particles.push({x,y:y+0.1,vx:Math.cos(a)*sp,vy:Math.abs(Math.sin(a))*sp*0.7+0.5,life:0.6+rnd()*0.9,t:0,r:0.04+rnd()*0.14});}
