}

function step(dt){
  if(state!=='running' && state!=='settled'){ // still allow bricks to settle if any motion? Keep static when ready
    // in ready state, keep wall perfectly still
    return;
  }
  elapsed+=dt;
  // car ground friction / rolling resistance when not powered after launch: mild decel, stronger after impact via collisions
  // Car is powered until impact? Keep constant speed until first brick contact handled by impulse; apply tiny drag
  car.vx -= car.vx*0.02*dt; // aero/rolling tiny
  // skid marks while moving fast
