  // iterations
  for(let it=0;it<4;it++){
    // ground
    for(const b of bricks) groundResolve(b);
    // car vs bricks: car as AABB-ish body (a=0)
    // broadphase: only bricks near car
    for(const b of bricks){
      if(Math.abs(b.x-car.x) > (CAR_W/2+b.w) ) continue;
      if(Math.abs(b.y-car.y) > (1.2+b.h) ) continue;
      const col=collide(car,b); if(col) resolvePair(car,b,col);
    }
    // brick-brick broadphase grid
    const cell=0.6; const map=new Map();
    bricks.forEach((b,i)=>{const k=Math.floor(b.x/cell)+':'+Math.floor(b.y/cell); if(!map.has(k))map.set(k,[]); map.get(k).push(i);});
    const seen=new Set();
    for(const b of bricks){
      const cx=Math.floor(b.x/cell), cy=Math.floor(b.y/cell);
      for(let gx=cx-1;gx<=cx+1;gx++)for(let gy=cy-1;gy<=cy+1;gy++){
        const arr=map.get(gx+':'+gy); if(!arr)continue;
        for(const j of arr){ const o=bricks[j]; if(o===b)continue; const key=bricks.indexOf(b)+'-'+j; if(seen.has(key))continue; seen.add(key);
          if(Math.abs(o.x-b.x)>0.65||Math.abs(o.y-b.y)>0.55)continue;
          const col=collide(b,o); if(col)resolvePair(b,o,col);
        }
      }
    }
    // keep car on ground, no rotation (visual tilt separate)
    car.y=0.62; car.vy=0; car.av=0; car.a=0;
    // left barrier / world bounds
    for(const b of bricks){ if(b.x<0.25){b.x=0.25;b.vx=Math.abs(b.vx)*0.3;} if(b.y>20){b.y=20;b.vy=0;} }
  }
  // car tilt / squash visual from deceleration
  const targetTilt = Math.max(-0.06, Math.min(0.09, -car.vx*0.0012 + (impactDone? -0.018:0)));
  carTilt += (targetTilt-carTilt)*0.08;
  carSquash = impactDone ? Math.max(0, carSquash*0.92) : 0; if(impactDone && carSquash===0) carSquash=0.04;
  // particles
  for(const p of particles){p.t+=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy-=2.5*dt;p.vx*=(1-1.5*dt);}
  particles=particles.filter(p=>p.t<p.life);
  shake*=0.88; if(shake<0.1)shake=0;
  // settle check
  let moving=0; for(const b of bricks) if(Math.hypot(b.vx,b.vy)>0.18||Math.abs(b.av)>0.25)moving++;
  if(elapsed>1 && moving===0 && Math.abs(car.vx)<0.05){ state='settled'; $('status').textContent='SETTLED — press Test to run again'; $('status').className='status'; }
  // safety: car stops at right edge
  if(car.x>38){car.x=38;car.vx=0;}
}
